namespace ghidra.app.plugin.core.label;





using docking.action;
using docking.action;
using ghidra.app.context;
using ghidra.app.context;
using ghidra.program.model.symbol;
using ghidra.program.model.symbol;
using ghidra.program.util;
using ghidra.program.util;

/**
 * <CODE>AddLabelAction</CODE> allows the user to add a label.
 */
class EditLabelAction : ListingContextAction {
	private LabelMgrPlugin plugin;

	static readonly string EDIT_LABEL = "Edit Label...";
	static readonly string EDIT_FIELDNAME = "Edit Field Name...";

	private static readonly string[] POPUP_PATH = new string[] { EDIT_LABEL };
	private static readonly KeyStroke KEYBINDING = KeyStroke.getKeyStroke(KeyEvent.VK_L, 0);

	/**
	 * Creates a new instance of the action.
	 *
	 * @param plugin Label Manager Plugin instance
	 */
	EditLabelAction(LabelMgrPlugin plugin) : base("Edit Label", plugin.getName())
    {

		setPopupMenuData(new MenuData(POPUP_PATH, null, "Label"));
		setKeyBindingData(new KeyBindingData(KEYBINDING));

		// Set the Group

		this.plugin = plugin;
		setEnabled(true);
	}

	/* @Override */
	protected bool isEnabledForContext(ListingActionContext context) {
		if (LabelMgrPlugin.getComponent(context) != null) {
			getPopupMenuData().setMenuItemName(EDIT_FIELDNAME);
			return true;
		}

		Symbol symbol = plugin.getSymbol(context);
		if (symbol == null) {
			return false;
		}

		if (symbol.isExternal()) {
			return false;
		}

		if (symbol.getSymbolType() == SymbolType.FUNCTION) {
			ProgramLocation location = context.getLocation();
			if (location is OperandFieldLocation) {
				// Functions in operand fields are handled by the EditNameAction.  Return false
				// here to prevent 2 popup actions from appearing in the menu.
				return false;
			}
		}

		getPopupMenuData().setMenuItemName(EDIT_LABEL);
		return true;
	}

	/* @Override */
	public void actionPerformed(ListingActionContext context) {
		plugin.editLabelCallback(context);
	}

}
